import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&/^parameters?_/.test(w))x[k]='$transaction';else if(k==='confirmation'&&typeof w==='string'&&w.length===32)x[k]='$confirmation';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text);}catch{}walk(v);return v;}
const rows=[];for(const tool of ['liveDeviceParameterPreview','liveDeviceParameterPreviewAsync','liveDeviceParameterApply','liveDeviceParameterApplyAsync']){const valid=tool.includes('Preview')?{deviceRef:'device:utility-1',parameterRef:'parameter:gain-1',value:.7}:{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of Object.keys(valid)){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,0,-4,.25,1,2000,'','x','a'.repeat(257)])cases.push({...valid,[key]:value});}if(tool.endsWith('PreviewAsync')){for(const values of [null,[],[{}],[{parameterRef:'parameter:gain-1',value:.7}],[{parameterRef:'parameter:gain-1',value:.7},{parameterRef:'parameter:gain-1',value:.8}],[{parameterRef:'bad',value:.4}],[{parameterRef:'parameter:gain-1',value:'.7'}]])cases.push({deviceRef:'device:utility-1',values});}for(const args of cases){const host=new McpHost(new DeterministicLiveSimulator());let result;try{result=clean(await host[tool](1,structuredClone(args)));}catch(e){result={error:e.message};}rows.push({tool,args,result});}}
const workflows=[];
for(const mode of ['sync','single','multi','listed','paged'])for(const scenario of (mode==='paged'?['normal']:['normal','expire','epoch','value-edit','identity-edit','owner-edit','track-edit','sibling-edit','disabled','device-disabled','not-automatable','clamp','quantize','rounded','rounded-too-far','apply-before','apply-after','apply-cancel','apply-refusal','apply-no-effect','apply-read','undo-before','undo-after','undo-refusal','undo-no-effect','undo-read','undo-current-read','undo-value-edit','undo-identity-edit'])){
 const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();let fault='',fired=false,afterInvoke=false;const device=sim.state.tracks[0].devices[0];const count=mode==='multi'?3:mode==='listed'?5:mode==='paged'?1025:1;const original=structuredClone(device.parameters[0]);device.parameters=Array.from({length:count},(_,i)=>({...original,ref:i?'parameter:p'+i:original.ref,objectIdentity:i?'parameter-identity-'+i:original.objectIdentity,name:i?'Knob '+i:original.name}));const first=()=>device.parameters[0];if(scenario==='disabled')first().enabled=false;if(scenario==='device-disabled')device.enabled=false;if(scenario==='not-automatable')first().automatable=false;if(scenario==='quantize')first().quantization=.25;if(scenario.startsWith('rounded'))for(const p of device.parameters)p.max=8;
 const value=scenario==='clamp'?8:scenario==='quantize'?.6:scenario==='rounded'?2.7:scenario==='rounded-too-far'?2.2:.7;
 function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
 function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure');}}
 function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(c&&cache.has(key))return cache.get(key);if(!fired&&['before','cancel','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error(fault.endsWith('cancel')?'operation cancelled before dispatch':'injected operation failure');}const noEffect=!fired&&fault.endsWith('no-effect');let result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else if(c)cache.set(key,result);if(scenario.startsWith('rounded')&&!afterInvoke){for(const p of device.parameters){p.value=3;p.displayValue='3';}}afterInvoke=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure');}return result;}
 const adapter={status:()=>sim.status(),snapshot:()=>{calls.push({method:'snapshotSync'});readFault();return sim.snapshot()},get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async(c)=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};
 const host=new McpHost(adapter),results=[],states=[];const args=count===1?{deviceRef:device.ref,parameterRef:first().ref,value}:{deviceRef:device.ref,values:device.parameters.map(p=>({parameterRef:p.ref,value}))};const suffix=mode==='sync'?'':'Async';const preview=await host['liveDeviceParameterPreview'+suffix](1,args);results.push(clean(preview));const body=JSON.parse(preview.result.content[0].text);const txid=body.transactionId;
 if(txid&&mode!=='paged'){const record=(count===1?host.deviceParameterTransactions:host.deviceParametersTransactions).get(txid);async function perform(action,key){const args={transactionId:txid,confirmation:action==='apply'?body.confirmation:'undo',idempotencyKey:key};results.push(clean(action==='apply'?await host['liveDeviceParameterApply'+suffix](results.length+1,args):await host['liveUndo'+suffix](results.length+1,args)));states.push(clean(record));}
 if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='value-edit')first().value=.3;if(scenario==='identity-edit')first().objectIdentity='other';if(scenario==='owner-edit')device.objectIdentity='other';if(scenario==='track-edit')sim.state.tracks[0].objectIdentity='other';if(scenario==='sibling-edit')device.parameters.push({...original,ref:'parameter:extra',objectIdentity:'extra'});if(scenario.startsWith('apply-'))fault=scenario;
 for(const key of ['apply-key','other-key','apply-key'])await perform('apply',key);fault='';fired=false;afterInvoke=false;
 if(scenario==='undo-value-edit'){first().value=.3;first().revision=20;}if(scenario==='undo-identity-edit')first().objectIdentity='other';if(scenario.startsWith('undo-')&&!['undo-value-edit','undo-identity-edit'].includes(scenario))fault=scenario;
 for(const key of ['undo-key','other-undo-key','undo-key'])await perform('undo',key);fault='';fired=false;afterInvoke=false;await perform('undo','new-undo-key');}
 workflows.push({mode,scenario,results,states,calls,device});
}
fs.writeFileSync(new URL('host-parameter-oracle.json',import.meta.url),JSON.stringify({rows,workflows}));console.log({rows:rows.length,workflows:workflows.length});
